private val leaves = java.util.concurrent.atomic.AtomicInteger()
fun lockOnLeave() { leaves.incrementAndGet(); vault.lock(LockReason.LEFT_APP) } // MainActivity.onStop calls this instead of vault.lock(LEFT_APP)

private suspend fun newVault(name: String, before: suspend (VaultStore) -> Unit = {}, made: suspend (VaultStore) -> Unit): String = changingVaults.withLock {
    if (!canAddVault()) throw VaultsRefused(VAULT_NEW_NEEDS_OPEN)
    val leftMark = leaves.get() // leaving the app from here on leaves the new vault locked
    ...
        before(store)
        switchTo(info.id)
        if (leaves.get() == leftMark && foreground) made(store)
        if (leaves.get() != leftMark || !foreground) store.lock(LockReason.LEFT_APP) // a leave during made
    ...
}

// in attempt(): read the master mark with the generation, before the snapshot
val markBefore = store.masterMark()
val written = copyTo(uri, folder, at) ?: return null
if (store.masterMark() != markBefore) {
    // Made under a master that changed meanwhile: never listed as a current copy; delete it now (best effort)
    // or hand its id to the saved A6 request of this target.
    runCatching { folder.delete(written.id) }
    return stale(uri, at, generation, replaceAll)
}
